327	// SubscribeAnnouncements subscribes to graph announcements on a topic.
328	func (dm *DHTManager) SubscribeAnnouncements(ctx context.Context, topic string) (<-chan []byte, error) {
329		if dm.IsNetworkPaused() {
330			return nil, fmt.Errorf("network is paused, cannot subscribe to topic %s", topic)
331		}
332	
333		t, err := dm.pubsub.Join(topic)
334		if err != nil {
335			return nil, fmt.Errorf("failed to join topic %s: %w", topic, err)
336		}
337	
338		sub, err := t.Subscribe()
339		if err != nil {
340			return nil, fmt.Errorf("failed to subscribe to topic %s: %w", topic, err)
341		}
342	
343		ch := make(chan []byte, 10)
344		go func() {
345			defer close(ch)
346			for {
347				select {
348				case <-ctx.Done():
349					return
350				default:
351					msg, err := sub.Next(ctx)
352					if err != nil {
353						if ctx.Err() == nil {
354							log.Printf("Error receiving announcement: %v", err)
355						}
356						return
357					}
358					ch <- msg.Data
359				}
360			}
361		}()
362	
363		return ch, nil
364	}
