372	func (dm *DHTManager) AnnounceAllCached(ctx context.Context) (int, error) {
373		resources := dm.resourceCache.GetAllResources()
374		announced := 0
375	
376		for _, res := range resources {
377			cid, err := createCID(res.ID, res.Type)
378			if err != nil {
379				log.Printf("Failed to create CID for resource %s: %v", res.ID, err)
380				continue
381			}
382	
383			if err := dm.kadDHT.Provide(ctx, cid, true); err != nil {
384				log.Printf("Failed to announce cached resource %s: %v", res.ID, err)
385				continue
386			}
387			announced++
388		}
389	
390		log.Printf("Announced %d/%d cached resources to DHT", announced, len(resources))
391		return announced, nil
392	}
393	
394	// startAnnouncementWorker periodically announces all cached resources.
395	func (dm *DHTManager) startAnnouncementWorker(ctx context.Context, interval time.Duration) {
396		ticker := time.NewTicker(interval)
397		defer ticker.Stop()
398	
399		for {
400			select {
401			case <-ticker.C:
402				resources := dm.resourceCache.GetAllResources()
403				for _, res := range resources {
404					cid, err := createCID(res.ID, res.Type)
405					if err != nil {
406						log.Printf("Failed to create CID for resource %s: %v", res.ID, err)
407						continue
408					}
409					// Use fresh context with timeout for each announcement
410					announceCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
411					if err := dm.kadDHT.Provide(announceCtx, cid, true); err != nil {
412						log.Printf("Failed to announce cached resource %s: %v", res.ID, err)
413					}
414					cancel()
415				}
416			case <-ctx.Done():
417				return
418			}
419		}
420	}
421	
422	// handleNetworkControl processes network control messages.
423	func (dm *DHTManager) handleNetworkControl() {
424		for {
425			select {
426			case <-dm.ctx.Done():
427				return
428			default:
429				msg, err := dm.networkControlSub.Next(dm.ctx)
430				if err != nil {
431					if dm.ctx.Err() == nil {
432						log.Printf("Error receiving network control message: %v", err)
433					}
434					continue
435				}
436	
437				if msg.ReceivedFrom == dm.host.ID() {
438					continue
439				}
440	
441				log.Printf("KNIRVGATEWAY received network control message")
442			}
443		}
444	}
445	
446	// handleGraphAnnouncements processes graph-related announcements.
447	func (dm *DHTManager) handleGraphAnnouncements() {
448		for {
449			select {
450			case <-dm.ctx.Done():
451				return
452			default:
453				msg, err := dm.graphSub.Next(dm.ctx)
454				if err != nil {
455					if dm.ctx.Err() == nil {
456						log.Printf("Error receiving graph announcement: %v", err)
457					}
458					continue
459				}
460	
461				if msg.ReceivedFrom == dm.host.ID() {
462					continue
463				}
464	
465				log.Printf("KNIRVGATEWAY received graph announcement")
466			}
467		}
468	}
469	
470	// announceService announces this KNIRVGATEWAY service to the DHT.
471	func (dm *DHTManager) announceService() {
472		cid, err := createCIDFromServiceID(dm.serviceID)
473		if err != nil {
474			log.Printf("Failed to create CID for service announcement: %v", err)
475			return
476		}
477	
478		if err := dm.kadDHT.Provide(dm.ctx, cid, true); err != nil {
479			log.Printf("Failed to announce KNIRVGATEWAY service: %v", err)
480			return
481		}
482	
483		log.Printf("Announced KNIRVGATEWAY service %s to DHT", dm.serviceID)
484	}
485	
486	// createCID creates a CID from a resource ID and type.
487	func createCID(id, resourceType string) (cid.Cid, error) {
488		hash, err := multihash.Sum([]byte(fmt.Sprintf("%s:%s", id, resourceType)), multihash.SHA2_256, -1)
489		if err != nil {
490			return cid.Cid{}, err
491		}
492		return cid.NewCidV1(cid.Raw, hash), nil
493	}
494	
495	// createCIDFromServiceID creates a CID from a service ID.
496	func createCIDFromServiceID(serviceID string) (cid.Cid, error) {
497		hash, err := multihash.Sum([]byte(serviceID), multihash.SHA2_256, -1)
498		if err != nil {
499			return cid.Cid{}, err
500		}
501		return cid.NewCidV1(cid.Raw, hash), nil
502	}
503	
504	// findOpenPort searches for an open port starting from preferredPort.
505	func findOpenPort(preferredPort, maxAttempts int) int {
506		for port := preferredPort; port < preferredPort+maxAttempts; port++ {
507			ln, err := net.Listen("tcp", fmt.Sprintf(":%d", port))
508			if err == nil {
509				ln.Close()
510				return port
511			}
512		}
513		return 0
514	}
