455	// registerSyncHandler registers the chain sync stream handler
456	func (pcm *P2PConsensusManager) registerSyncHandler() {
457		pcm.host.SetStreamHandler(ChainSyncProtocolID, pcm.handleSyncStream)
458		log.Printf("[%s][%s] Registered chain sync handler for protocol %s", pcm.nodeRole.String(), pcm.blockchain.GetChainID(), ChainSyncProtocolID)
459	}
460	
461	// handleSyncStream handles incoming chain sync requests
462	func (pcm *P2PConsensusManager) handleSyncStream(stream network.Stream) {
463		defer stream.Close()
464		nodeID := stream.Conn().RemotePeer()
465		log.Printf("[%s][%s] Received chain sync stream from %s", pcm.nodeRole.String(), pcm.blockchain.GetChainID(), nodeID)
466	
467		reader := bufio.NewReader(stream)
468		writer := bufio.NewWriter(stream)
469		decoder := json.NewDecoder(reader)
470		encoder := json.NewEncoder(writer)
471	
472		// Read request type
473		var request map[string]interface{}
474		if err := decoder.Decode(&request); err != nil {
475			log.Printf("[%s][%s] Error decoding sync request from %s: %v", pcm.nodeRole.String(), pcm.blockchain.GetChainID(), nodeID, err)
476			return
477		}
478	
479		// Handle different request types
480		if _, ok := request["getStatus"]; ok {
481			// The value associated with "getStatus" would be an empty map if GetStatusRequest{} was sent.
482			// This is fine as handleStatusRequest doesn't use the content of GetStatusRequest.
483			pcm.handleStatusRequest(encoder, writer)
484		} else if getBlocksPayload, ok := request["getBlocks"]; ok {
485			// getBlocksPayload is the GetBlocksRequest struct, likely unmarshaled as map[string]interface{}
486			getBlocksMap, ok := getBlocksPayload.(map[string]interface{})
487			if !ok {
488				log.Printf("[%s][%s] Invalid 'getBlocks' payload structure from %s", pcm.nodeRole.String(), pcm.blockchain.GetChainID(), nodeID)
489				return
490			}
491			startAfterFloat, ok := getBlocksMap["start_after"].(float64) // JSON numbers are float64
492			if !ok {
493				log.Printf("[%s][%s] Invalid 'start_after' in getBlocks request from %s", pcm.nodeRole.String(), pcm.blockchain.GetChainID(), nodeID)
494				return
495			}
496			pcm.handleBlocksRequest(uint64(startAfterFloat), encoder, writer)
497		} else {
498			log.Printf("[%s][%s] Received unknown sync request from %s: %v", pcm.nodeRole.String(), pcm.blockchain.GetChainID(), nodeID, request)
499		}
500	}
501	
502	func (pcm *P2PConsensusManager) handleStatusRequest(encoder *json.Encoder, writer *bufio.Writer) {
503		pcm.blockchain.Lock()
504		blocks := pcm.blockchain.GetBlocks().([]*Block)
505		lastBlock := blocks[len(blocks)-1]
506		pcm.blockchain.Unlock()
507	
508		response := StatusResponse{
509			LatestBlockNumber: lastBlock.BlockNumber,
510			LatestBlockHash:   lastBlock.HashString(),
511		}
512	
513		if err := encoder.Encode(response); err != nil {
514			log.Printf("[%s][%s] Error encoding status response: %v", pcm.nodeRole.String(), pcm.blockchain.GetChainID(), err)
515			return
516		}
517		if err := writer.Flush(); err != nil {
518			log.Printf("[%s][%s] Error flushing status response: %v", pcm.nodeRole.String(), pcm.blockchain.GetChainID(), err)
519		}
