// DiscoveryResourceType represents a DHT resource type.
type DiscoveryResourceType string

const (
	DiscoveryResourceTypeChain         DiscoveryResourceType = "chain"
	DiscoveryResourceTypeNRN          DiscoveryResourceType = "nrn"
