func (pcm *P2PConsensusManager) runForkResolution() {
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			// Skip if we're actively mining
			if pcm.blockchain.IsActivelyMining() {
				continue
			}

			// Request chain data from nodes
			pcm.requestChainFromPeers()

