		pcm.nodeRole.String(), pcm.blockchain.GetChainID(), currentChainLength, len(newChain))

	pcm.blockchain.SetBlocks(newChain)
	if err := pcm.db.PutIntoDb(pcm.blockchain, pcm.blockchain.GetChainAddress()); err != nil {
		log.Printf("[%s][%s] Failed to save updated blockchain: %v", pcm.nodeRole.String(), pcm.blockchain.GetChainID(), err)
	}
