// P2PConsensusManager manages consensus via KNIRVGATEWAY P2P proxy.
type P2PConsensusManager struct {
	blockchain Blockchain
	db         DB
	nodeRole   config.Role
	ctx        context.Context
	cancel     context.CancelFunc

	gatewaySocket string
	gatewayClient *http.Client

	miningLocked   bool
	isSyncing      bool
	networkPaused  bool
	pausedUntil    time.Time
	updateRequired bool
	mu             sync.Mutex
	stopChan       chan struct{}
}

// NewP2PConsensusManager creates a new gateway-proxied P2P consensus manager.
func NewP2PConsensusManager(blockchain Blockchain, db DB, discoveryManager DiscoveryService, role config.Role) (*P2PConsensusManager, error) {
	ctx, cancel := context.WithCancel(context.Background())

	gatewaySocket := ""
	if dm, ok := discoveryManager.(interface{ GetGatewaySocket() string }); ok {
		gatewaySocket = dm.GetGatewaySocket()
	}

	var gatewayClient *http.Client
	if gatewaySocket != "" {
		gatewayClient = &http.Client{
			Timeout: 10 * time.Second,
			Transport: &http.Transport{
				DialContext: func(gctx context.Context, _, _ string) (net.Conn, error) {
					return (&net.Dialer{}).DialContext(gctx, "unix", gatewaySocket)
				},
			},
		}
	}

	chainID := blockchain.GetChainID()
	blockTopicName := fmt.Sprintf("%s.%s", chainID, BlockTopic)
	txTopicName := fmt.Sprintf("%s.%s", chainID, TransactionTopic)

	log.Printf("[%s][%s] Using default topic validation settings", role.String(), chainID)
	log.Printf("[%s][%s] P2P consensus manager subscribed to topics: %s, %s, %s",
		role.String(), chainID, blockTopicName, txTopicName, NetworkControlTopic)

	manager := &P2PConsensusManager{
		blockchain:    blockchain,
		db:            db,
		nodeRole:      role,
		ctx:           ctx,
		cancel:        cancel,
		gatewaySocket: gatewaySocket,
		gatewayClient: gatewayClient,
		stopChan:      make(chan struct{}),
	}

	log.Printf("[%s][%s] Registered chain sync handler for protocol %s", role.String(), chainID, ChainSyncProtocolID)

	return manager, nil
}

// Start begins the consensus process.
func (pcm *P2PConsensusManager) Start() {
	log.Printf("[%s][%s] Starting P2P consensus manager...", pcm.nodeRole.String(), pcm.blockchain.GetChainID())
	go pcm.runForkResolution()
	log.Printf("[%s][%s] P2P consensus manager started successfully.", pcm.nodeRole.String(), pcm.blockchain.GetChainID())
}

