func convertToP2PTransaction(tx *Transaction) *p2p.Transaction {
	return &p2p.Transaction{
		TransactionHash: tx.TransactionHash,
		Type:            tx.Type,
		From:            tx.From,
		Data:            tx.Data,
	}
}

func convertToP2PBlock(block *Block) *p2p.Block {
	// Convert InvalidTxHashes from map[string]string to map[string]bool
	invalidTxHashes := make(map[string]bool)
	for k := range block.InvalidTxHashes {
		invalidTxHashes[k] = true
	}

	return &p2p.Block{
		BlockNumber:     block.BlockNumber,
		Timestamp:       block.Timestamp,
		Transactions:    convertTransactionsToP2P(block.Transactions),
		InvalidTxHashes: invalidTxHashes,
		PrevHash:        hex.EncodeToString(block.PrevHash),
		Hash:            hex.EncodeToString(block.BlockHash),
	}
}

func convertTransactionsToP2P(txs []*Transaction) []*p2p.Transaction {
	result := make([]*p2p.Transaction, len(txs))
	for i, tx := range txs {
		result[i] = convertToP2PTransaction(tx)
	}
	return result
}

